def phi(x,p):return np.prod(x[:,None,:]**np.array(p),axis=-1)
def fit(z,y):
 b=np.linalg.lstsq(z,y,rcond=None)[0]
 for s in [.4,.1,.02,.004,.001,.00035,.0002,.0002]:
